import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void commonFifoAndFailures(){for(int i=0;i<3;i++){Object q=TaskBinding.queue(i,2);assertEquals("",capture(()->{TaskBinding.put(q,'A');TaskBinding.put(q,'B');}));if(i<2)assertEquals("Очередь переполнена\n",capture(()->TaskBinding.put(q,'C')));else assertEquals("",capture(()->TaskBinding.put(q,'C')));assertEquals("",capture(()->{assertEquals('A',TaskBinding.get(q));assertEquals('B',TaskBinding.get(q));}));if(i==2)assertEquals('C',TaskBinding.get(q));assertEquals("Очередь пуста\n",capture(()->assertEquals('\0',TaskBinding.get(q))));}}}
